import ast

# Find Product class and check __init__ method
tree = ast.parse(code)

for node in ast.walk(tree):
    if isinstance(node, ast.ClassDef) and node.name == 'Product':
        # Look for __init__ method
        has_init = False
        for item in node.body:
            if isinstance(item, ast.FunctionDef) and item.name == '__init__':
                has_init = True

                # Check parameters (self, name, price, in_stock)
                args = item.args.args
                arg_names = [arg.arg for arg in args]

                if len(arg_names) < 3:
                    raise AssertionError('__init__ should have at least self, name, and price parameters')

                if arg_names[0] != 'self':
                    raise AssertionError('First parameter of __init__ should be self')

                if 'name' not in arg_names:
                    raise AssertionError('__init__ missing name parameter')

                if 'price' not in arg_names:
                    raise AssertionError('__init__ missing price parameter')

                # Check for default value on in_stock
                defaults = item.args.defaults
                if len(defaults) > 0:
                    # There's at least one default parameter
                    pass
                else:
                    # Check if in_stock is in args but might not have default
                    if 'in_stock' in arg_names and arg_names.index('in_stock') >= len(arg_names) - len(defaults):
                        # in_stock has a default
                        pass
                    elif 'in_stock' in arg_names:
                        # in_stock exists but we can't verify default from AST easily
                        # We'll trust the student and check functionality in later tests
                        pass

                break

        if not has_init:
            raise AssertionError('Product class should have an __init__ method')
        break

